#[path="../native-prepared-solvers/tail.rs"]mod tail;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn key<'a>(line:&'a str,k:&str)->Option<&'a str>{line.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn nonaudit(s:&str)->String{let(a,b)=s.split_once("dense_audits: ").unwrap();let(_,b)=b.split_once(',').unwrap();format!("{a}dense_audits: 0,{b}")}
fn main(){let old=include_str!("../native-affine-forest/CONTROL.txt");let mut calls=0;for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let c=&inst.curve;let mut rng=Rng::new(2026111800^p^((g as u64)<<32));for case in 0..2{let sm=if case==0{1}else{17};let d=c.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=c.mul(&d,k);let oldout=old.lines().find(|l|l.starts_with("OUTCOME ")&&key(l,"g")==Some(v[0])&&key(l,"p")==Some(v[1])&&key(l,"sm")==Some(sm.to_string().as_str())&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"rep")==Some("0")).unwrap().split("report=").nth(1).unwrap();let mut prior=None;for rep in 0..2{counted::disable();descriptor::clear();assert!(validate::eligible(c,&d,&t,ell));let prep=prepared::prepare(c,true);eprintln!("start g={g} p={p} sm={sm} rep={rep}");let report=pencil::solve(c,&d,&t,ell,512,true,&prep);assert_eq!(report.k,Some(k));assert_eq!(c.mul(&d,k),t);assert_eq!(nonaudit(&format!("{report:?}")),oldout);let doc=descriptor::take().expect("first rho1 descriptor must exist on fixed panel");let state=(doc.clone(),format!("{report:?}"));if let Some(ref previous)=prior{assert_eq!(previous,&state);}else{prior=Some(state);}let nonzero_b=doc.grounded.iter().enumerate().any(|(j,&yes)|yes&&doc.b[j]!=0);println!("DESCRIPTOR g={g} p={p} sm={sm} case={case} rep={rep} admitted={} grounded={} rank={} beta_nonzero={nonzero_b} raw_checked={} witness={:?}",doc.admitted,doc.grounded.iter().filter(|x|**x).count(),doc.rank,doc.raw_checked,doc.witness);for j in 0..doc.grounded.len(){if doc.grounded[j]{println!("POINT g={g} p={p} sm={sm} case={case} rep={rep} j={j} alpha={} beta={}",doc.a[j],doc.b[j]);}}for(modulus,values)in doc.counts{assert_eq!(values[8],2*values[7]+values[5]+values[6]);println!("DESCRIPTOR_COUNT g={g} p={p} sm={sm} case={case} rep={rep} modulus={modulus} vector={values:?}");}calls+=1;}}}assert_eq!(calls,44);eprintln!("PASS calls=44 all_first_rho1_descriptors=true full_raw_equations_hold=true original_outcomes_replay=true repeated_descriptors_and_component_counts_exact=true native_answers=true no_integrated_cost_or_tenfold_claim=true");}
